values := []int{72, 85, 64, 90, 85, 58, 77, 85, 69, 93, 71}
sorted := slices.Clone(values)
slices.Sort(sorted)
mode, best, count := sorted[0], 0, 0
for i, n := range sorted {
	if i > 0 && n == sorted[i-1] {
		count++
	} else {
		count = 1
	}
	if count > best {
		best, mode = count, n
	}
}
